/**
 * Expanded question bank — 550 hand-written questions added to grow the daily
 * and practice pools. The later batches broaden the mix toward modern pop
 * culture — movies, TV, video games, music, tech, and internet culture —
 * alongside the evergreen topics. The three most recent batches of 50 pull
 * back the other way to even out the category mix: they feed the thin
 * categories (Nature most of all, then art, the human body, mythology,
 * literature, internet, pop culture, and technology) while keeping a
 * pop-culture share, since the practice
 * picker steers away from repeating a category and a lopsided bank makes that
 * harder.
 *
 * Most of these were written to the older spec §2.2 rules, which put
 * misdirection first, so many are easier than we now want. Between 2026-10-04
 * and 2026-10-10, 200 of them were rewritten to the current rules with
 * pipeline/fix-clues.ts, in four rounds of 50. The before and after, with a
 * source for each new fact, are in clueEval/results/rewrites-2026-10-04.json
 * (round 1), rewrites-2026-10-04-round-2.json (round 2),
 * rewrites-2026-10-05.json (round 3) and rewrites-2026-10-10.json (round 4).
 * The current rules
 * for writing and rewriting clues are in lib/questions/README.md, under "What
 * makes a good question". Follow those, not the style of the entries below.
 *
 * These merge into the local bank after SEED_QUESTIONS and (when present) the
 * gitignored private bank. They are validated by the same integrity suite.
 */

